-- Flyer-Verteilung (/flyer/): people who sign up to distribute the
-- campaign flyer and the streets they take on.

CREATE TABLE flyer_signups (
	id INTEGER PRIMARY KEY AUTOINCREMENT,
	created_at TEXT NOT NULL DEFAULT (datetime('now')),
	first_name TEXT NOT NULL,
	last_name TEXT NOT NULL,
	street TEXT NOT NULL, -- Strasse und Nr.
	zip_city TEXT NOT NULL, -- PLZ und Ort
	note TEXT,
	ip TEXT NOT NULL
);

-- rate limit lookup: sign-ups per IP in the last 24 hours
CREATE INDEX idx_flyer_signups_ip_created ON flyer_signups (ip, created_at);

-- A street is "vergeben" as soon as signup_id is set. geometry is GeoJSON
-- (WGS84) for the map; streets added later in the admin panel have none.
CREATE TABLE flyer_streets (
	id INTEGER PRIMARY KEY AUTOINCREMENT,
	name TEXT NOT NULL,
	zip TEXT,
	geometry TEXT,
	signup_id INTEGER REFERENCES flyer_signups (id) ON DELETE SET NULL
);

CREATE INDEX idx_flyer_streets_signup ON flyer_streets (signup_id);

-- One-time import from the official street directory of Wangen SZ
-- (swisstopo, ch.swisstopo.amtliches-strassenverzeichnis, com_fosnr 1349),
-- coordinates rounded to 5 decimals (~1 m), one statement per street (D1
-- limits a single statement to 100 KB). Later changes happen in /admin/flyer/.
